(async()=>{save(session);initMicroInteractions();const identity=telegramMode?initializeTelegramSession():null;try{if(!telegramMode){await authCallback();if(session?.expires_at<Date.now()/1000+60)await refreshSession();await adminCheck()}}catch(e){console.error("Authentication initialization failed")}await load();window.P2PTelegram?.appReady();if(identity)await identity;track("page_view");if(session){await loadFavs();render(cars)}})();

let errorRecorded=false;function recordClientError(){if(errorRecorded)return;errorRecorded=true;track("client_error")}window.addEventListener("error",recordClientError);window.addEventListener("unhandledrejection",recordClientError);

function adminReportOpen(btn){const card=btn.closest(".report-card");if(card)detail(card.dataset.listing,0,"admin-reports")}
function adminReportStatus(btn,status){const card=btn.closest(".report-card");if(card)setReportStatus(Number(card.dataset.report),status)}
function adminReportRemove(btn){const card=btn.closest(".report-card");if(card)adminSetListingStatus(card.dataset.listing,"removed")}
function renderAdminReports(reports){if(!reports.length)return '<p>No reports.</p>';return reports.map(r=>{const img=r.image_path?'<img class="report-thumb" src="'+esc(photoUrl(r.image_path))+'" alt="Reported vehicle">':'';const more=r.details?'<div class="report-details">'+esc(r.details)+'</div>':'';const statusClass=r.report_status==="open"?"open":"closed";const reporter=r.reporter_telegram?'@'+esc(r.reporter_telegram):esc(r.reporter_email||'No public contact');const seller=r.seller_telegram?'@'+esc(r.seller_telegram):esc(r.seller_name||'Unknown');return '<div class="report-card" data-listing="'+esc(r.listing_id)+'" data-report="'+Number(r.report_id)+'">'+img+'<div class="report-main"><div class="report-top"><span class="report-status '+statusClass+'">'+esc(r.report_status)+'</span><small>'+new Date(r.reported_at).toLocaleString()+'</small></div><h3>'+esc(r.reason)+'</h3>'+more+'<div class="report-section"><b>Reported listing</b><div>'+Number(r.listing_year)+' '+esc(r.listing_make)+' '+esc(r.listing_model)+' · $'+Number(r.listing_price).toLocaleString()+' CAD · '+esc(r.listing_status)+'</div><small>Seller: '+seller+'</small></div><div class="report-section"><b>Reported by</b><div>'+esc(r.reporter_name||"User")+'</div><small>'+reporter+'</small></div><div class="actions report-actions"><button class="secondary" onclick="adminReportOpen(this)">Open listing</button><button class="secondary" onclick="adminReportStatus(this,&quot;reviewed&quot;)">Reviewed</button><button class="secondary" onclick="adminReportStatus(this,&quot;dismissed&quot;)">Dismiss</button><button class="danger" onclick="adminReportRemove(this)">Remove listing</button></div></div></div>'}).join("")}
